SELECT

FROM
iot_product_model
WHERE
del_flag = '0'

    AND product_id = #{model.productId}


    AND func_type = #{model.funcType}


    AND identifier LIKE CONCAT('%', #{model.identifier}, '%')


    AND name LIKE CONCAT('%', #{model.name}, '%')


    AND data_type = #{model.dataType}


    AND factory_code = #{model.factoryCode}

ORDER BY create_time DESC

SELECT *
FROM iot_product_model
WHERE product_id = #{productId}
  AND identifier = #{identifier}
  AND del_flag = '0' LIMIT 1
